/* Pointer-chase timed part shared by Q2 / Q4 / Q5 (native + enclave).
 *
 * kt_setup(NULL, 0, mb_per_chain, seed, thp) builds two independent random
 * cyclic pointer chains, each over its own buffer much larger than the LLC,
 * so every load is a cache miss. In the SGX build the buffers come from the
 * enclave heap, i.e. encrypted EPC memory with 4 KB pages.
 *
 * kt_run(i, iters) times kernel i of chase_table (generated by gen_chase.py);
 * the chain positions persist between runs so lines are not revisited soon. */
#include <stdlib.h>
#ifndef IN_ENCLAVE
#include <stdio.h>
#include <sys/mman.h>
#endif

#include "bench.h"
#include "kt.h"

struct chase_entry {
    void (*fn)(void **p, void **q, uint64_t iters);
    const char *kind;
    uint64_t n;
};
extern const struct chase_entry chase_table[];
extern const uint64_t chase_table_len;

#define LINE 64   /* one node per cache line */

static void *p, *q;

static char *alloc_buf(size_t bytes, int thp)
{
#ifdef IN_ENCLAVE
    (void)thp;
    char *raw = malloc(bytes + LINE);
    if (!raw)
        return NULL;
    return (char *)(((uintptr_t)raw + LINE - 1) & ~(uintptr_t)(LINE - 1));
#else
    void *buf = mmap(NULL, bytes, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buf == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }
#ifdef MADV_HUGEPAGE
    madvise(buf, bytes, thp ? MADV_HUGEPAGE : MADV_NOHUGEPAGE);
#endif
    return buf;
#endif
}

/* Random single-cycle permutation (Sattolo) over the buffer's cache lines. */
static void *build_chain(size_t bytes, int thp, uint64_t *seed)
{
    char *base = alloc_buf(bytes, thp);
    size_t nodes = bytes / LINE;
    uint32_t *perm = malloc(nodes * sizeof(*perm));
    if (!base || !perm)
        return NULL;
    for (size_t i = 0; i < nodes; i++)
        perm[i] = i;
    for (size_t i = nodes - 1; i > 0; i--) {
        size_t j = xorshift64(seed) % i;   /* j < i: Sattolo -> one big cycle */
        uint32_t tmp = perm[i];
        perm[i] = perm[j];
        perm[j] = tmp;
    }
    for (size_t i = 0; i < nodes; i++)
        *(void **)(base + (size_t)perm[i] * LINE) = base + (size_t)perm[(i + 1) % nodes] * LINE;
    free(perm);
    return base;
}

uint64_t kt_count(void)
{
    return chase_table_len;
}

void kt_entry(uint64_t i, char *name, size_t cap, uint64_t *a, uint64_t *b)
{
    kt_copy_name(name, cap, i < chase_table_len ? chase_table[i].kind : "?");
    *a = i < chase_table_len ? chase_table[i].n : 0;
    *b = 0;
}

int kt_setup(const void *data, size_t len, uint64_t mb, uint64_t seed, uint64_t thp)
{
    (void)data, (void)len;
    p = build_chain(mb << 20, (int)thp, &seed);
    q = build_chain(mb << 20, (int)thp, &seed);
    return p && q ? 0 : -1;
}

uint64_t kt_run(uint64_t i, uint64_t iters)
{
    if (i >= chase_table_len || !p)
        return 0;
    uint64_t t0 = tsc_start();
    chase_table[i].fn(&p, &q, iters);
    return tsc_stop() - t0;
}
